<template>
 <div class="page-container enterprise-page">
  <div class="page-header"><div class="page-header-title"><h1>调度集群监控</h1><p>集群、业务日期、运行实例与项目告警统一查看</p></div><div class="page-actions"><router-link class="btn btn-ghost" to="/dolphinscheduler">连接管理</router-link><button class="btn btn-primary" :disabled="!cluster || busy" @click="sync">立即采集</button><button class="btn btn-ghost" :disabled="busy" @click="load">刷新</button></div></div>
  <p v-if="error" class="inline-error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p>
