  <section v-if="failures.length" class="card status-warning" role="status"><strong>采集异常或数据延迟</strong><p v-for="c in failures" :key="c.lane">{{ c.lane }} · {{ c.error_message || '数据已过期' }} · 最后成功 {{ c.last_success || '尚未成功' }}。下方保留最近一次成功数据。</p></section>
  <template v-if="tab==='overview' && dashboard">
   <div class="metrics"><div v-for="m in metricCards" :key="m.label" class="card metric"><span>{{ m.label }}</span><strong>{{ m.value ?? '未知' }}</strong></div></div>
