   <section class="card"><h2 class="card-title">采集状态</h2><div class="table-wrap"><table class="table"><thead><tr><th>采集任务</th><th>状态</th><th>最后成功</th><th>连续失败</th></tr></thead><tbody><tr v-for="c in primaryCollection" :key="c.lane"><td>{{ c.lane }}</td><td><span :class="['badge',collectionFresh(c)?'badge-up':'badge-unknown']">{{ collectionFresh(c)?'正常':'等待 / 延迟 / 失败' }}</span></td><td>{{ c.last_success || '尚未成功' }}</td><td>{{ c.failures }}</td></tr></tbody></table></div></section>
  </template>
  <template v-if="tab==='projects'">
   <section class="card"><h2 class="card-title">项目定义与权限</h2><p v-if="!project">选择一个项目查看工作流、任务定义和授权关系。</p><template v-else><p>上线 {{ currentProject?.online_count ?? '未知' }} · 下线 {{ currentProject?.offline_count ?? '未知' }} · 已启用定时 {{ currentProject?.schedule_count ?? '未知' }} · 定时状态未知 {{ currentProject?.unknown_schedule_count ?? '未知' }} · 任务定义 {{ currentProject?.task_definition_count ?? '未知' }}</p><div class="page-actions"><label>定义类型<select v-model="definitionKind" class="form-control" @change="loadDefinitions"><option value="workflow_definition">工作流定义</option><option value="task_definition">任务定义</option></select></label><button class="btn btn-ghost" @click="loadDefinitions">查询定义与授权</button><button class="btn btn-ghost" @click="editProject">配置责任人</button></div><p class="form-hint">上线与定时分别统计；定时状态未知不会算作已关闭。</p><div class="table-wrap"><table class="table"><thead><tr><th>工作流</th><th>定义编码</th><th>发布状态</th><th>定时状态</th><th>任务节点数</th><th>最近采集运行</th><th>所有者</th></tr></thead><tbody><tr v-for="d in definitionPager.items" :key="d.id"><td><button class="link-button" @click="openDefinition(d)">{{ d.name }}</button></td><td>{{ d.id }}</td><td>{{ d.releaseState || d.taskType || '未知' }}</td><td>{{ d.scheduleReleaseState || '未知' }}</td><td>{{ d.task_count ?? '未知' }}</td><td>{{ d.last_collected_run || '未知' }}</td><td>{{ d.userName || '未知' }}</td></tr></tbody></table></div><PaginationControls v-model:page="definitionPager.page" v-model:page-size="definitionPager.pageSize" :total="definitionPager.total" label="工作流定义" /><p>授权用户：{{ authorizations.map(a=>a.userName).join('、') || '无已同步授权关系（所有者单独同步）' }}</p></template></section>
  </template>
  <template v-if="tab==='instances'">
   <section class="card"><div class="filters"><label>记录类型<select v-model="kind" class="form-control" @change="queryInstances"><option value="workflow_instance">工作流实例</option><option value="task_instance">任务实例</option></select></label><label>工作流编码<input v-model="workflow" class="form-control" @change="queryInstances"></label><label v-if="kind==='task_instance'">任务编码<input v-model="task" class="form-control" @change="queryInstances"></label><label>状态<select v-model="state" class="form-control" @change="queryInstances"><option value="">全部状态</option><option v-for="s in stateOptions" :key="s">{{ s }}</option></select></label><label>执行开始时间<input v-model="start" type="datetime-local" class="form-control"></label><label>执行截止时间<input v-model="end" type="datetime-local" class="form-control"></label><button class="btn btn-primary" @click="queryInstances">查询</button></div><p class="form-hint">ETL_Date 来自参数；UNKNOWN 表示未取得明确业务日期。记录按稳定实例 ID 保存，包含重跑记录。</p><div class="table-wrap"><table class="table"><thead><tr><th>名称 / 实例 ID</th><th>工作流 / 任务编码</th><th>ETL_Date / 来源</th><th>状态</th><th>开始 / 结束</th><th>耗时 / 重试</th><th>节点 / 用户</th><th>日志 / 原因</th></tr></thead><tbody><tr v-for="r in instances.items" :key="r.id"><td>{{ r.name }}<small>{{ r.id }}</small></td><td>{{ r.definition_code }}<small>{{ r.task_code }}</small></td><td>{{ r.etl_date || 'UNKNOWN' }}<small>{{ r.etl_date_source }}</small></td><td><span :class="['badge',r.state==='FAILURE'?'badge-down':r.state==='SUCCESS'?'badge-up':'badge-info']">{{ r.state }}</span></td><td>{{ r.start_time || '—' }}<br>{{ r.end_time || '—' }}</td><td>{{ r.duration || '—' }}<small>重试 {{ r.retry_times || r.run_times || 0 }}</small></td><td>{{ r.host || '未知' }}<small>{{ r.executor || '未知' }}</small><small v-for="n in r.running_nodes || []" :key="n.id">{{ n.name }} · {{ n.host || '未知' }} · {{ n.state }}</small></td><td><button v-if="kind==='task_instance' && r.log_available" class="btn btn-ghost btn-sm" @click="showLog(r)">日志</button><span v-else>—</span><small>{{ r.failure_reason }}</small></td></tr></tbody></table></div><div class="page-actions"><button class="btn btn-ghost" :disabled="instances.page<=1" @click="instancePage--;queryInstances(false)">上一页</button><span>第 {{ instances.page || 1 }} 页 · 共 {{ instances.total ?? '未知' }} 条</span><button class="btn btn-ghost" :disabled="!instances.total || instances.page*20>=instances.total" @click="instancePage++;queryInstances(false)">下一页</button></div></section>
   <section class="card"><h2 class="card-title">按业务日期汇总任务执行</h2><div class="table-wrap"><table class="table"><thead><tr><th>业务日期</th><th>任务实例次数</th><th>运行</th><th>成功</th><th>失败</th><th>等待</th><th>未成功（实例次数）</th><th>最新尝试完成率</th></tr></thead><tbody><tr v-for="d in dates" :key="d.etl_date"><td><button class="link-button" :disabled="d.etl_date==='UNKNOWN'" @click="date=d.etl_date;kind='task_instance';queryInstances()">{{ d.etl_date }}</button></td><td>{{ d.total }}</td><td>{{ d.running }}</td><td>{{ d.success }}</td><td>{{ d.failed }}</td><td>{{ d.waiting }}</td><td>{{ d.unfinished }}</td><td>{{ d.completion_rate == null ? '未知' : Number(d.completion_rate).toFixed(1)+'%' }}</td></tr></tbody></table></div></section>
  </template>
  <template v-if="tab==='resources' && dashboard">
   <section class="card"><h2 class="card-title">Master / Worker</h2><p class="form-hint">物理内存来自 resInfo；JVM 通过已有 SSH 主机映射执行只读 jstat。堆比例以 committed 为分母；GCT 为累计 GC 时间。</p><div class="table-wrap"><table class="table"><thead><tr><th>角色 / 节点</th><th>心跳 / 状态</th><th>CPU</th><th>主机内存</th><th>JVM 堆 / GC</th><th>可用磁盘 / 负载</th><th>等待 / 执行线程</th><th>历史</th></tr></thead><tbody><tr v-for="n in dashboard.nodes" :key="n.id"><td>{{ n.role }}<small>{{ n.host }}:{{ n.port }}</small></td><td><span :class="['badge',n.online&&collectionFresh(resourceCollection)?'badge-up':'badge-unknown']">{{ collectionFresh(resourceCollection)?n.online?'在线':'离线 / 心跳过期':'数据过期' }}</span><small>{{ n.heartbeat }}</small><small v-if="Math.abs(n.source_clock_skew_seconds || 0)>60">源时钟偏差 {{ Number(n.source_clock_skew_seconds).toFixed(0) }} 秒（已校正判断）</small></td><td>{{ pct(n.cpu_percent) }}</td><td>{{ pct(n.host_memory_percent) }}</td><td>{{ n.jvm_available?pct(n.heap_committed_percent):'不可用' }}<small v-if="n.heap_max_bytes">堆上限 {{ mb(n.heap_max_bytes) }} MB · {{ pct(n.heap_max_percent) }}</small><small v-if="n.jvm_available">{{ mb(n.heap_used_bytes) }} / {{ mb(n.heap_committed_bytes) }} MB · GC {{ n.gc_time_seconds }} s</small><small v-else>{{ n.jvm_unavailable_reason }}</small></td><td>{{ n.disk_available_gb ?? '未知' }} GB / {{ n.load_average ?? '未知' }}</td><td>{{ n.waiting_tasks ?? '未知' }} / {{ n.execution_threads ?? '未知' }}<small>关联运行 {{ n.running_instances ?? '未知' }}</small></td><td><button class="btn btn-ghost btn-sm" @click="showHistory(n)">趋势</button></td></tr></tbody></table></div><h3>元数据库</h3><p v-for="d in dashboard.databases" :key="d.id">{{ d.dbType }} · {{ d.state }} · 活跃连接 {{ d.threadsRunningConnections ?? '未知' }} / {{ d.maxConnections ?? '未知' }}</p></section>
  </template>
  <template v-if="tab==='alerts'">
   <section class="card"><div class="card-header"><h2 class="card-title">项目告警</h2><router-link :to="'/alerts/tasks?service_id='+cluster">发送任务与重试记录 →</router-link></div><div class="page-actions"><button class="btn btn-primary" :disabled="!project" @click="editProject">配置所选项目责任人与告警组</button><button class="btn btn-ghost" @click="editingRule=true">新增 / 覆盖规则</button></div><p class="form-hint">规则优先级：任务 → 工作流 → 项目 → 平台。责任人为空或项目无接收组时转交默认运维组；相同实例异常去重，恢复单独记录。</p><div class="table-wrap"><table class="table"><thead><tr><th>项目</th><th>异常类型</th><th>说明</th><th>状态</th><th>发生 / 恢复</th></tr></thead><tbody><tr v-for="i in incidentPager.items" :key="i.incident_key"><td>{{ i.project_code || '平台' }}</td><td>{{ i.category }}</td><td>{{ i.message }}</td><td>{{ Number(i.active)===2?'聚合抑制':Number(i.active)===1?'待恢复':'已恢复' }}</td><td>{{ i.opened_at }}<br>{{ i.resolved_at }}</td></tr></tbody></table></div><PaginationControls v-model:page="incidentPager.page" v-model:page-size="incidentPager.pageSize" :total="incidentPager.total" label="告警事件" /></section>
   <section class="card"><h2 class="card-title">已配置规则</h2><div class="table-wrap"><table class="table"><thead><tr><th>范围</th><th>类型</th><th>阈值 / 日期</th><th>启用</th></tr></thead><tbody><tr v-for="r in rules" :key="r.scope_type+':'+r.scope_id+':'+r.rule_type"><td>{{ r.scope_type }}:{{ r.scope_id }}</td><td>{{ r.rule_type }}</td><td>{{ r.threshold_value ?? r.business_date }} {{ r.deadline }}</td><td>{{ r.enabled?'是':'否' }}</td></tr></tbody></table></div></section>
  </template>
  <template v-if="tab==='settings' && selected">
   <section class="card"><h2 class="card-title">集群采集与通知</h2><form @submit.prevent="saveSettings"><div class="filters"><label>接口配置档<select v-model="settings.api_profile" class="form-control"><option value="generic">通用 REST（明确日期）</option><option value="ld-2.0.8">已核验 ld-2.0.8</option></select></label><label><input type="checkbox" v-model="settings.resolve_verified_system_dates">依据已核验逻辑调度时间解析业务日期</label><label><input type="checkbox" v-model="settings.enterprise_enabled">启用企业采集</label><label><input type="checkbox" v-model="settings.enterprise_alerts_enabled">启用项目与集群告警</label><label><input type="checkbox" v-model="settings.collect_jvm">通过已有 SSH 映射采集 JVM</label><label>定义同步（秒）<input class="form-control" type="number" min="15" max="86400" v-model.number="settings.inventory_interval_seconds"></label><label>用户同步（秒）<input class="form-control" type="number" min="15" max="86400" v-model.number="settings.users_interval_seconds"></label><label>运行采集（秒）<input class="form-control" type="number" min="15" max="86400" v-model.number="settings.runtime_interval_seconds"></label><label>资源采样（秒）<input class="form-control" type="number" min="10" max="86400" v-model.number="settings.resources_interval_seconds"></label><label>接口超时（秒）<input class="form-control" type="number" min="1" max="60" v-model.number="settings.api_timeout_seconds"></label><label>失败重试（次）<input class="form-control" type="number" min="0" max="3" v-model.number="settings.api_retries"></label><label>首次实例窗口（小时）<input class="form-control" type="number" min="1" max="744" v-model.number="settings.initial_window_hours"></label><label>心跳过期（秒）<input class="form-control" type="number" min="30" max="3600" v-model.number="settings.heartbeat_timeout_seconds"></label><label>保留天数<input class="form-control" type="number" min="1" max="3650" v-model.number="settings.retention_days"></label><label>业务日期参数名（逗号分隔）<input class="form-control" v-model="settings.etl_date_keys" placeholder="ETL_Date,dataDate,RQ,@rq"></label><label>默认运维告警组<select multiple class="form-control" v-model="settings.default_ops_group_ids"><option v-for="g in groups" :key="g.id" :value="g.id">{{ g.group_name }}</option></select></label></div><p class="form-hint">现场 ld-2.0.8 已验证。JVM 需要已维护的 SSH 主机凭据及 jstat；缺失指标保留未知。生产通知会发往所选既有渠道。</p><div class="page-actions"><button class="btn btn-primary" :disabled="busy">保存配置</button><button type="button" class="btn btn-ghost" @click="testConnection">只读连接测试</button></div></form></section>
  </template>
  <DetailDrawer :open="editingProject" title="项目责任人与告警组" @close="editingProject=false"><form @submit.prevent="saveProject"><p>项目 {{ project }} · 所有者 {{ currentProject?.owner || '未知' }}，与业务责任人分别保存。</p><label class="form-group">主要责任人<input v-model="projectForm.primary_owner" class="form-control" list="ds-users" maxlength="255"></label><label class="form-group">备用责任人<input v-model="projectForm.backup_owner" class="form-control" list="ds-users" maxlength="255"></label><datalist id="ds-users"><option v-for="u in users" :key="u.id" :value="u.userName" /></datalist><label class="form-group">接收告警组<select multiple v-model="projectForm.group_ids" class="form-control"><option v-for="g in groups" :key="g.id" :value="g.id">{{ g.group_name }}</option></select></label><label><input v-model="projectForm.alert_enabled" type="checkbox">启用项目告警</label><p class="form-hint">告警组内已有渠道定义实际接收对象，请确保组内接收人包含责任人。仅设置姓名不会新增邮件或短信接收人。</p><button class="btn btn-primary">保存</button></form></DetailDrawer>
  <DetailDrawer :open="editingRule" title="告警规则覆盖" @close="editingRule=false"><form @submit.prevent="saveRule"><label class="form-group">范围<select v-model="ruleForm.scope_type" class="form-control"><option value="platform">平台</option><option value="project">项目</option><option value="workflow">工作流</option><option value="task">任务</option></select></label><label class="form-group">范围编码<input v-model="ruleForm.scope_id" class="form-control" required placeholder="平台填 *，其余填写稳定编码"></label><label class="form-group">规则类型<select v-model="ruleForm.rule_type" class="form-control"><option v-for="r in ruleTypes" :key="r" :value="r">{{ r }}</option></select></label><label class="form-group">阈值<input v-model.number="ruleForm.threshold_value" type="number" min="0" class="form-control"><small>超时单位秒，磁盘单位 GB，资源使用率单位 %，积压单位任务数</small></label><template v-if="ruleForm.rule_type==='ETL_DEADLINE'"><label class="form-group">目标业务日期<input type="date" required v-model="ruleForm.business_date" class="form-control"></label><label class="form-group">截止时间<input type="datetime-local" required v-model="ruleForm.deadline" class="form-control"></label></template><label><input v-model="ruleForm.enabled" type="checkbox">启用规则（取消可覆盖停用）</label><button class="btn btn-primary">保存规则</button></form></DetailDrawer>
  <DetailDrawer :open="!!logTask" title="任务日志" @close="logTask=null"><template v-if="logTask"><p>实例 {{ logTask.id }}，每次最多 100 行</p><pre class="task-log">{{ logContent || '无日志内容' }}</pre><div class="page-actions"><button class="btn btn-ghost" :disabled="logOffset===0" @click="logOffset=Math.max(0,logOffset-100);loadLog()">上一段</button><button class="btn btn-ghost" @click="logOffset+=100;loadLog()">下一段</button></div></template></DetailDrawer>
  <DetailDrawer :open="!!historyNode" title="节点资源趋势" @close="historyNode=null"><template v-if="historyNode"><p>{{ historyNode.host }} · {{ historyNode.role }}</p><select v-model.number="historyHours" @change="loadHistory" class="form-control"><option :value="1">近 1 小时</option><option :value="24">近 24 小时</option><option :value="168">近 7 天</option></select><div ref="chartEl" style="height:320px;width:100%"></div><p class="form-hint">CPU、主机内存与已提交堆使用率分别绘制，缺失采样断开显示；48 小时以前按小时均值归档。</p></template></DetailDrawer>
 </div>
</template>
<script setup>
import {ref,computed,onMounted,onBeforeUnmount,nextTick} from 'vue'
import * as echarts from 'echarts'
import {api} from '../api'
import DetailDrawer from '../components/DetailDrawer.vue'
import PaginationControls from '../components/PaginationControls.vue'
import {usePagination} from '../composables/usePagination'
const connections=ref([]),cluster=ref(''),project=ref(''),date=ref(''),tab=ref('overview'),dashboard=ref(null),busy=ref(false),error=ref(''),notice=ref(''),groups=ref([]),users=ref([]),definitions=ref([]),authorizations=ref([]),incidents=ref([]),rules=ref([]),dates=ref([]),instances=ref({items:[],page:1,total:null})
const definitionKind=ref('workflow_definition'),kind=ref('workflow_instance'),workflow=ref(''),task=ref(''),state=ref(''),start=ref(''),end=ref(''),instancePage=ref(1),settings=ref({}),editingProject=ref(false),projectForm=ref({}),editingRule=ref(false),ruleForm=ref({scope_type:'project',scope_id:'',rule_type:'WORKFLOW_FAILURE',threshold_value:1,enabled:true}),logTask=ref(null),logContent=ref(''),logOffset=ref(0),historyNode=ref(null),historyHours=ref(24),chartEl=ref(null)
const tabs=[{key:'overview',name:'企业驾驶舱'},{key:'projects',name:'项目监控'},{key:'instances',name:'任务运行明细'},{key:'resources',name:'集群资源'},{key:'alerts',name:'项目告警'},{key:'settings',name:'采集配置'}]
const stateOptions=['RUNNING_EXECUTION','SUBMITTED_SUCCESS','SUCCESS','FORCED_SUCCESS','FAILURE','STOP','KILL','PAUSE','DELAY_EXECUTION','SERIAL_WAIT','WAITING_THREAD','WAITING_DEPEND','NEED_FAULT_TOLERANCE']
const ruleTypes=['WORKFLOW_FAILURE','TASK_FAILURE','TIMEOUT','ETL_DEADLINE','BACKLOG','CPU_HIGH','MEMORY_HIGH','JVM_HIGH','DISK_LOW']
const selected=computed(()=>connections.value.find(c=>String(c.id)===cluster.value)),currentProject=computed(()=>dashboard.value?.projects.find(p=>p.id===project.value)),metricCards=computed(()=>[{label:'项目',value:dashboard.value?.project_count},{label:'上线工作流',value:dashboard.value?.online_workflows},{label:'任务定义',value:dashboard.value?.task_definitions},{label:'运行工作流',value:dashboard.value?.workflow_statistics?.running},{label:'失败工作流',value:dashboard.value?.workflow_statistics?.failed},{label:'待发送 / 重试',value:dashboard.value?.pending_deliveries}])
const projectPager=usePagination(()=>dashboard.value?.projects || []),definitionPager=usePagination(definitions,[project]),incidentPager=usePagination(incidents)
const collectionFresh=c=>c?.fresh!==undefined?c.fresh:!!c?.last_success&&!c.failures&&Date.now()-new Date(c.last_success.replace(' ','T')+'+08:00').getTime()<(Number(settings.value[(c.lane.split(':')[0])+'_interval_seconds'])||300)*3000
const failures=computed(()=>(dashboard.value?.collection || []).filter(c=>c.failures || c.last_success&&!collectionFresh(c))),primaryCollection=computed(()=>['inventory','runtime','resources','users'].map(lane=>(dashboard.value?.collection || []).find(c=>c.lane===lane)||{lane})),resourceCollection=computed(()=>primaryCollection.value.find(c=>c.lane==='resources'))
const pct=v=>v==null?'未知':Number(v).toFixed(1)+'%',mb=v=>v==null?'未知':(Number(v)/1048576).toFixed(0)
let generation=0,queryGeneration=0,timer,chart
async function guarded(fn){error.value='';try{await fn()}catch(e){error.value=e.message}}
async function call(path,params={},method='GET',body){return api.dolphinEnterprise(cluster.value,path,params,method,body)}
async function load(){if(!cluster.value)return;const id=cluster.value,n=generation;busy.value=true;await guarded(async()=>{const [data,events,configured]=await Promise.all([call('/dashboard'),call('/incidents'),call('/rules')]);if(id!==cluster.value||n!==generation)return;dashboard.value=data;incidents.value=events;rules.value=configured;if(tab.value==='instances')await queryInstances(false)});busy.value=false}
async function changeCluster(){++generation;dashboard.value=null;project.value='';definitions.value=[];instances.value={items:[],page:1,total:null};date.value='';workflow.value='';task.value='';error.value='';try{const config=JSON.parse(selected.value?.config_json || '{}');settings.value={enterprise_enabled:false,enterprise_alerts_enabled:false,collect_jvm:false,api_profile:'generic',resolve_verified_system_dates:false,inventory_interval_seconds:300,users_interval_seconds:300,runtime_interval_seconds:30,resources_interval_seconds:15,api_timeout_seconds:15,api_retries:1,initial_window_hours:24,heartbeat_timeout_seconds:120,retention_days:90,etl_date_keys:'ETL_Date,etl_date,etlDate,dataDate',default_ops_group_ids:[],...config}}catch{settings.value={}}await load();await guarded(async()=>{users.value=await call('/users')})}
async function sync(){await guarded(async()=>{await call('/sync',{},'POST');notice.value='采集任务已提交，首次定义同步可能需要数分钟。';await load()})}
async function queryInstances(reset=true){if(!cluster.value)return;if(reset)instancePage.value=1;const id=cluster.value,p=project.value,q=++queryGeneration;await guarded(async()=>{const [rows,summary]=await Promise.all([call('/instances',{kind:kind.value,project:p,workflow:workflow.value,task:task.value,state:state.value,etl_date:date.value,start:start.value?(start.value.length===16?start.value+':00':start.value):'',end:end.value?(end.value.length===16?end.value+':59':end.value):'',page:instancePage.value,page_size:20}),call('/business-dates',{project:p})]);if(id!==cluster.value||p!==project.value||q!==queryGeneration)return;instances.value=rows;instancePage.value=rows.page;dates.value=summary})}
function selectTab(key){tab.value=key;if(key==='instances')queryInstances();if(key==='projects'&&project.value)loadDefinitions()}
function changeProject(){workflow.value='';task.value='';queryInstances();if(tab.value==='projects')loadDefinitions()}
async function loadDefinitions(){await guarded(async()=>{[definitions.value,authorizations.value]=await Promise.all([call('/definitions',{project:project.value,kind:definitionKind.value}),call('/projects/'+project.value+'/authorizations')])})}
function openDefinition(d){workflow.value=d.definition_code || d.id;task.value=d.task_code || '';kind.value=d.task_code?'task_instance':'workflow_instance';tab.value='instances';queryInstances()}
async function openProject(p){project.value=p.id;workflow.value='';task.value='';tab.value='projects';await loadDefinitions()}
function editProject(){if(!project.value)return;const c=currentProject.value?.config || {};projectForm.value={primary_owner:c.primary_owner || '',backup_owner:c.backup_owner || '',group_ids:JSON.parse(c.group_ids || '[]'),alert_enabled:c.alert_enabled!==0};editingProject.value=true}
async function saveProject(){await guarded(async()=>{await call('/projects/'+project.value+'/config',{},'PUT',projectForm.value);editingProject.value=false;await load()})}
async function saveRule(){await guarded(async()=>{const body={...ruleForm.value};if(body.deadline)body.deadline=body.deadline.replace('T',' ')+(body.deadline.length===16?':00':'');await call('/rules',{},'PUT',body);editingRule.value=false;await load()})}
async function saveSettings(){await guarded(async()=>{const data={...selected.value,service_type:'dolphinscheduler',config:{...settings.value},check_interval_unit:'seconds',check_interval_value:selected.value.check_interval};delete data.secret_config_json;await api.saveDolphinConnection(selected.value.id,data);connections.value=await api.dolphinConnections();notice.value='集群配置已保存';await load()})}
async function testConnection(){await guarded(async()=>{const r=await call('/test',{},'POST');notice.value='连接正常，可访问 '+r.project_count+' 个项目'})}
async function showLog(row){logTask.value=row;logOffset.value=0;await loadLog()}
async function loadLog(){logContent.value='';await guarded(async()=>{const result=await call('/logs/'+logTask.value.id,{offset:logOffset.value,limit:100});logContent.value=result.content})}
async function showHistory(node){historyNode.value=node;await nextTick();await loadHistory()}
async function loadHistory(){await guarded(async()=>{const rows=await call('/nodes/'+encodeURIComponent(historyNode.value.id)+'/history',{hours:historyHours.value});await nextTick();if(!chartEl.value)return;if(chart)chart.dispose();chart=echarts.init(chartEl.value);chart.setOption({tooltip:{trigger:'axis'},legend:{data:['CPU','主机内存','JVM 已提交堆']},grid:{left:45,right:15,bottom:55},xAxis:{type:'category',data:rows.map(r=>r.sampled_at)},yAxis:{type:'value',min:0,max:100,axisLabel:{formatter:'{value}%'}},dataZoom:[{type:'inside'},{type:'slider',height:15}],series:[['CPU','cpu_percent'],['主机内存','host_memory_percent'],['JVM 已提交堆','heap_committed_percent']].map(([name,key])=>({name,type:'line',showSymbol:false,connectNulls:false,data:rows.map(r=>r.metrics_stale?null:r[key]??null)}))})})}
onMounted(async()=>{await guarded(async()=>{[connections.value,groups.value]=await Promise.all([api.dolphinConnections(),api.listAlertGroups()]);cluster.value=String(connections.value[0]?.id || '');if(cluster.value)await changeCluster()});timer=setInterval(()=>{if(!editingProject.value&&!editingRule.value&&!busy.value)load()},30000)})
onBeforeUnmount(()=>{generation++;clearInterval(timer);chart?.dispose()})
</script>
<style scoped>
.tabs{display:flex;gap:8px;flex-wrap:wrap;margin:0 0 20px}.filters{display:flex;flex-wrap:wrap;align-items:end;gap:14px}.filters label{display:flex;flex-direction:column;gap:7px;min-width:180px;flex:1;font-size:13px}.metrics{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:14px}.metric span{color:var(--text-muted);font-size:13px}.metric strong{display:block;font-size:28px;margin-top:12px}.table td{max-width:360px;word-break:break-word}.table small{display:block;color:var(--text-muted);margin-top:4px}.link-button{border:0;background:none;padding:0;color:#0284c7;cursor:pointer;text-align:left;font:inherit}.status-warning{border-color:#f59e0b;background:#fffbeb}.status-warning p{font-size:12px;margin:8px 0 0}.form-group{display:flex;flex-direction:column;gap:8px;margin:15px 0}.task-log{white-space:pre-wrap;overflow-wrap:anywhere;background:#0f172a;color:#e2e8f0;padding:16px;max-height:65vh;overflow:auto}.page-actions{flex-wrap:wrap}@media(max-width:900px){.metrics{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:600px){.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.filters label{min-width:100%;}.tabs .btn{flex:1;white-space:nowrap}}
</style>
